import React, { useState } from "react";
import api from "../api";
import { useNavigate } from "react-router-dom";

const FullAdmissionForm = () => {
  const navigate = useNavigate();
  const [form, setForm] = useState({
    studentName: "",
    parentName: "",
    classApplied: "",
    age: "",
    phone: "",
    email: "",
    address: "",
    photo: null
  });

  const [status, setStatus] = useState("");
  const [photoPreview, setPhotoPreview] = useState(null);

  const change = (e) => {
    const { name, value, files } = e.target;
    if (name === "photo" && files.length > 0) {
      setForm((f) => ({ ...f, photo: files[0] }));
      setPhotoPreview(URL.createObjectURL(files[0])); // preview the image
    } else {
      setForm((f) => ({ ...f, [name]: value }));
    }
  };

  const validateForm = () => {
    if (!form.studentName || !form.parentName || !form.classApplied) return false;
    if (!form.phone.match(/^[0-9]{10}$/)) return false;
    if (!form.email.match(/^[^@ ]+@[^@ ]+\.[^@ .]{2,}$/)) return false;
    if (!form.photo) return false;
    return true;
  };

  const submit = async (e) => {
    e.preventDefault();
    if (!validateForm()) {
      setStatus("Please fill all required fields correctly and upload a photo.");
      return;
    }

    setStatus("Submitting...");
    try {
      const formData = new FormData();
      Object.keys(form).forEach((key) => formData.append(key, form[key]));
      await api.post("/admissions", formData, {
        headers: { "Content-Type": "multipart/form-data" }
      });
      setStatus("Form submitted successfully!");
      setForm({
        studentName: "",
        parentName: "",
        classApplied: "",
        age: "",
        phone: "",
        email: "",
        address: "",
        photo: null
      });
      setPhotoPreview(null);

      setTimeout(() => navigate("/thank-you"), 1000);

    } catch (err) {
      console.error(err);
      setStatus("Submission failed. Please try again.");
    }
  };

  return (
    <div className="full-form-page">
      <h2>Full Admission Form</h2>
      <form onSubmit={submit} className="full-admission-form">
        <input name="studentName" placeholder="Student Name *" value={form.studentName} onChange={change} required />
        <input name="parentName" placeholder="Parent Name *" value={form.parentName} onChange={change} required />
        <input name="classApplied" placeholder="Class Applied *" value={form.classApplied} onChange={change} required />
        <input name="phone" placeholder="Phone (10 digits) *" value={form.phone} onChange={change} required />
        <input name="email" placeholder="Email *" value={form.email} onChange={change} required />
        <textarea name="address" placeholder="Address *" value={form.address} onChange={change} required></textarea>
        
        <input type="file" name="photo" onChange={change} accept="image/*" required />

        {/* Photo preview */}
        {photoPreview && (
          <div className="photo-preview">
            <p>Photo Preview:</p>
            <img src={photoPreview} alt="Preview" className="preview-img" />
          </div>
        )}

        {/* Optional fields */}
        <input name="age" placeholder="Age (optional)" value={form.age} onChange={change} />

        <button type="submit">Submit</button>
        <div className="status">{status}</div>
      </form>
    </div>
  );
};

export default FullAdmissionForm;
